import json

raw_outputs = [
    '{"sku": "A1", "qty": 2}',
    '```json\n{"sku": "B2", "qty": "3"}\n```',
    "{'sku': 'C3', 'qty': 1}",
    '{"sku": "D4"}',
]

def parse(raw):
    text = raw.strip().removeprefix("```json").removesuffix("```").strip()
    try:
        data = json.loads(text)
    except json.JSONDecodeError:
        return "bad json"
    if not isinstance(data.get("qty"), int):
        return "bad qty"
    return f"{data['sku']} x{data['qty']}"

for r in raw_outputs:
    print(parse(r))

